SELECT oi.id, oi.order_id, oi.product_id, oi.sku_id, oi.product_name, oi.sku_spec, oi.main_image, oi.price, oi.quantity, oi.subtotal, oi.create_time, ps.sku_code AS sku_code FROM mo_order_item oi LEFT JOIN mo_product_sku ps ON ps.id = oi.sku_id WHERE oi.order_id IN
#{orderId}
ORDER BY oi.order_id ASC, oi.id ASC
